package com.ahope.ds.common.aws.kms;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * AWS KMS 클라이언트 및 암호화 서비스 Bean 설정.
 * <p>
 * {@link AwsKmsProperties}에서 region, CMK alias 정보를 읽어
 * 용도별 {@link AwsKmsEncryptionService} Bean을 생성한다.
 * <p>
 * 모든 KMS 호출은 AWS Encryption SDK의 MasterKeyProvider를 통해 수행한다.
 * <p>
 * CMK 분리 정책 (해킹 사고 영향 최소화):
 * <ul>
 *   <li>locationEncryptionService — CMK 1: 위치/트래픽 (ECGI, GPS) PI-0 등급</li>
 *   <li>dataEncryptionService — CMK 2: 개인정보 (CTN, IMEI 등) PI-0 외 등급</li>
 *   <li>AwsKmsFileService — CMK 3: 파일 암호화 (별도 클래스)</li>
 *   <li>tokenEncryptionService — CMK 4: 토큰 암복호화 (ACCESS_TOKEN, REFRESH_TOKEN)</li>
 * </ul>
 */
@Configuration
@EnableConfigurationProperties(AwsKmsProperties.class)
public class AwsKmsConfig {

    /**
     * CMK 1: 위치/트래픽 데이터 (ECGI, GPS) 암복호화 서비스 — PI-0 등급.
     * AWS Encryption SDK + Data Key Caching 사용.
     */
    @Bean
    public AwsKmsEncryptionService locationEncryptionService(AwsKmsProperties properties) {
        return new AwsKmsEncryptionService(
