		this.put("data", null);
	}

	public void setCode(String code) {
		this.put("code", code);
	}

	public String getCode() {
		Object code = this.get("code");
		return code != null ? code.toString() : "";
	}

	public void setMessage(String message) {
		this.put("message", message);
	}

