package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.nullValue;

import java.sql.Connection;
import java.sql.DriverManager;
import java.time.LocalDateTime;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientAPIController (/client)
 * @target-api GET /client/sync
 * Test Plan: .nimbus/artifacts/test-plan/ClientAPIService_sync.md
 *
 * 인터셉터: ClientLoginInterceptor (/client/** 전체 적용)
 *  - Authorization: Bearer {CMK-4로 암호화된 토큰 JSON} 필수
 *  - 토큰 payload: {"tokenType":"ACCESS","expiredAt":"yyyyMMddHHmmss","memberSeq":N,"clientSeq":N}
 *  - 검증 실패 시에도 CommonClientController의 전역 @ExceptionHandler가 HTTP 200 + JSON code로 응답
 * 외부 연동: 없음 (LocalStack KMS만 사용, WireMock 대상 아님 - detect-external-calls must_mock=[])
 * DB 의존: TERMS, NOTICE, CLIENT, CLIENT_ADDITIONAL_INFO, INTERWORKING_APP, ECGI,
 *          CLIENT_USAGE_SOLN_PKG, SOLN_MULTI_LANG_TEXT, MEMBER_BAN_SOLN_PKG
 */
class ClientSyncBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/client-sync-setup.sql", ClientSyncBlackBoxTest.class);
        // ECGI 컬럼을 LocalStack KMS(CMK-1)로 암호화 — 서버가 응답 시 decrypt하므로 필수
        TestUtil.encryptEcgi(dbConnection, 97801, "5551110001");
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    private static final LocalDateTime FUTURE = LocalDateTime.now().plusYears(1);
    private static final LocalDateTime PAST = LocalDateTime.of(2000, 1, 1, 0, 0, 0);

    private io.restassured.specification.RequestSpecification baseHeaders(String authorization) {
        return given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", authorization);
    }

    // ==================== NTC ====================

    /** [NTC_sync_fullClientData] 연동앱(안드로이드만 필터), ECGI, 솔루션이 모두 존재하는 정상 케이스 */
    @Test
    void NTC_sync_fullClientData() {
        String token = TestUtil.buildClientAccessToken(97801, 97801, "ACCESS", FUTURE);

        baseHeaders("Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("200"))
            .body("message", equalTo("OK"))
            .body("data.latestTermsVersion", equalTo(42))
            .body("data.latestNoticeVersion", equalTo(142))
            .body("data.mainBackgroundImageUrl", equalTo("https://img.example.com/bg-97801.png"))
            .body("data.interlockingAppVersion", equalTo(7))
            .body("data.interlockingAppList.size()", equalTo(1))
            .body("data.interlockingAppList[0].appName", equalTo("AndroidApp"))
            .body("data.interlockingAppList[0].packageName", equalTo("com.test.android"))
            .body("data.allowedEcgiList.size()", equalTo(1))
            .body("data.allowedEcgiList[0]", equalTo("5551110001"))
            .body("data.solutionList.size()", equalTo(1))
            .body("data.solutionList[0].solutionId", equalTo(97801))
            .body("data.solutionList[0].solutionName", equalTo("TestSolutionA"))
            .body("data.solutionList[0].enabled", equalTo(true));
    }

    /** [NTC_sync_bannedSolution_disabled] MEMBER_BAN_SOLN_PKG에 매칭되는 가입자는 solutionList[].enabled=false */
    @Test
    void NTC_sync_bannedSolution_disabled() {
        String token = TestUtil.buildClientAccessToken(97802, 97802, "ACCESS", FUTURE);

        baseHeaders("Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("200"))
            .body("data.interlockingAppList.size()", equalTo(0))
            .body("data.allowedEcgiList.size()", equalTo(0))
            .body("data.solutionList.size()", equalTo(1))
            .body("data.solutionList[0].solutionId", equalTo(97802))
            .body("data.solutionList[0].solutionName", equalTo("BannedSolutionB"))
            .body("data.solutionList[0].enabled", equalTo(false));
    }

    /** [NTC_sync_noAdditionalInfo_nullFields] CLIENT_ADDITIONAL_INFO 없는 고객사는 관련 필드가 null (예외 아님) */
    @Test
    void NTC_sync_noAdditionalInfo_nullFields() {
        String token = TestUtil.buildClientAccessToken(97803, 97803, "ACCESS", FUTURE);

        baseHeaders("Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("200"))
            .body("data.mainBackgroundImageUrl", nullValue())
            .body("data.interlockingAppVersion", nullValue())
            .body("data.interlockingAppList.size()", equalTo(0))
            .body("data.allowedEcgiList.size()", equalTo(0))
            .body("data.solutionList.size()", equalTo(0));
    }

    // ==================== ATC — 인증 토큰 분기 (ClientLoginInterceptor) ====================

    /** [ATC_sync_missingAuthorization] Authorization 헤더 없음 → 816 MISSING_TOKEN_VALUE */
    @Test
    void ATC_sync_missingAuthorization() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("816"))
            .body("message", equalTo("MISSING_TOKEN_VALUE"));
    }

    /** [ATC_sync_invalidAuthorizationFormat] "Bearer " 접두어 없음 → 812 INVALID_TOKEN */
    @Test
    void ATC_sync_invalidAuthorizationFormat() {
        baseHeaders("InvalidScheme abc123")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("812"))
            .body("message", equalTo("INVALID_TOKEN"));
    }

    /** [ATC_sync_undecryptableToken] Bearer 뒤 값이 KMS로 복호화 불가능한 임의 문자열 → 812 INVALID_TOKEN */
    @Test
    void ATC_sync_undecryptableToken() {
        baseHeaders("Bearer not-a-valid-kms-ciphertext")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("812"))
            .body("message", equalTo("INVALID_TOKEN"));
    }

    /** [ATC_sync_wrongTokenType] tokenType이 ACCESS가 아님 → 855 INVALID_TOKEN_TYPE */
    @Test
    void ATC_sync_wrongTokenType() {
        String token = TestUtil.buildClientAccessToken(97801, 97801, "REFRESH", FUTURE);

        baseHeaders("Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("855"))
            .body("message", equalTo("INVALID_TOKEN_TYPE"));
    }

    /** [ATC_sync_expiredToken] expiredAt이 과거 → 802 TOKEN_EXPIRED */
    @Test
    void ATC_sync_expiredToken() {
        String token = TestUtil.buildClientAccessToken(97801, 97801, "ACCESS", PAST);

        baseHeaders("Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("802"))
            .body("message", equalTo("TOKEN_EXPIRED"));
    }

    // ==================== VTC — 필수 헤더 누락 ====================

    /** [VTC_sync_missingManufacturerHeader] X-Manufacturer 헤더 누락 → 011 MISSING_REQUIRED_VALUE */
    @Test
    void VTC_sync_missingManufacturerHeader() {
        String token = TestUtil.buildClientAccessToken(97801, 97801, "ACCESS", FUTURE);

        given().log().all().baseUri(BASE_URL)
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
            .header("Authorization", "Bearer " + token)
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("011"))
            .body("message", equalTo("MISSING_REQUIRED_VALUE: X-Manufacturer"));
    }
}

