package com.ahope.ds.web.superadmin.crypto.service;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;

import com.ahope.ds.common.aws.kms.AwsKmsEncryptionService;
import com.ahope.ds.common.bean.ParamMap;
import com.ahope.ds.common.bean.ResultMap;
import com.ahope.ds.common.web.service.CommonService;
import com.ahope.ds.web.superadmin.crypto.dao.CryptoDAO;

import com.ahope.ds.common.securityModules.HashUtil;

@Service
public class CryptoService extends CommonService  {

	@Autowired
	@Qualifier("locationEncryptionService")
	private AwsKmsEncryptionService locationEncryptionService;

	@Autowired
	@Qualifier("dataEncryptionService")
	private AwsKmsEncryptionService dataEncryptionService;

	@Autowired
	private HashUtil hashUtil;

	@Autowired
	private CryptoDAO cryptoDAO;

	public ResultMap getLocationDecryption(ParamMap param) {
		ResultMap result = new ResultMap();
		String cryptoContent = param.getString("cryptoContent").trim();
		try {
			result.put("cryptoResult", locationEncryptionService.decrypt(cryptoContent));
		} catch (RuntimeException e) {
			result.setErr("115");
			logger.warn("[getLocationDecryption] invalid ciphertext: {}", e.getMessage());
		} catch (Exception e) {
			result.setErr("001");
			logger.error("[getLocationDecryption] {}", e.getMessage());
		}
		return result;
	}

	public ResultMap getPersonalDecryption(ParamMap param) {
		ResultMap result = new ResultMap();
		String cryptoContent = param.getString("cryptoContent").trim();
		try {
			result.put("cryptoResult", dataEncryptionService.decrypt(cryptoContent));
		} catch (RuntimeException e) {
			result.setErr("115");
			logger.warn("[getPersonalDecryption] invalid ciphertext: {}", e.getMessage());
		} catch (Exception e) {
			result.setErr("001");
			logger.error("[getPersonalDecryption] {}", e.getMessage());
		}
		return result;
	}

	public ResultMap getHashResult(ParamMap param) {
		ResultMap result = new ResultMap();
		String cryptoContent = param.getString("cryptoContent").trim();
		try {
			result.put("cryptoResult", hashUtil.hmacSha256(cryptoContent));
		} catch (Exception e) {
			result.setErr("001");
			logger.error("[getHashResult] {}", e.getMessage());
		}
		return result;
	}

	public ResultMap findMemberByCtn(ParamMap param) {
		ResultMap result = new ResultMap();
		String ctn = param.getString("cryptoContent").trim();
		try {
			String ctnHash = hashUtil.hmacSha256(ctn);
			ResultMap member = cryptoDAO.getMemberByCtn(ctnHash);
			if (member == null) {
				result.setErr("009");
			} else {
				result.put("clientSeq", member.get("clientSeq"));
				result.put("memberSeq", member.get("memberSeq"));
			}
		} catch (Exception e) {
			result.setErr("001");
			logger.error("[findMemberByCtn] {}", e.getMessage());
		}
		return result;
	}
