package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test
 *
 * @target-controller CryptoController (/web/super/admin/crypto)
 * @target-api POST /web/super/admin/crypto/personal
 *
 * 인터셉터: SuperAdminLoginInterceptor (/web/super/admin/** 적용, AUTHZ='07' 시스템 관리자로 검증)
 * 외부 연동: 없음 (LocalStack KMS(CMK-2, dataEncryptionService)만 사용 - detect-external-calls 대상 아님)
 * DB 의존: ACCOUNT (로그인), ACCOUNT_SMS (로그인 인증번호)
 */
class CryptoPersonalBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/superadmin-crypto-personal-teardown.sql", CryptoPersonalBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/superadmin-crypto-personal-setup.sql", CryptoPersonalBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "cryptopadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/superadmin-crypto-personal-teardown.sql", CryptoPersonalBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC ====================

    /** [NTC_getPersonalDecryption_success] CMK-2로 암호화된 개인정보(CTN)를 복호화 */
    @Test
    void NTC_getPersonalDecryption_success() {
        String cipher = TestUtil.kmsEncrypt("01099998888");

        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo("01099998888"));
    }

    /** [NTC_getPersonalDecryption_differentValue] CTN 이외의 임의 개인정보 문자열도 복호화 가능 */
    @Test
    void NTC_getPersonalDecryption_differentValue() {
        String cipher = TestUtil.kmsEncrypt("990101-1234567");

        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo("990101-1234567"));
    }

    /** [NTC_getPersonalDecryption_trimsWhitespace] cryptoContent 앞뒤 공백은 trim 후 복호화 (CryptoService#getPersonalDecryption) */
    @Test
    void NTC_getPersonalDecryption_trimsWhitespace() {
        String cipher = TestUtil.kmsEncrypt("01077776666");

        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", "  " + cipher + "  ")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo("01077776666"));
    }

    // ==================== VTC — cryptoContent 필수값 ====================

    /** [VTC_getPersonalDecryption_missingCryptoContent] cryptoContent 파라미터 자체가 없음 → 001 */
    @Test
    void VTC_getPersonalDecryption_missingCryptoContent() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("001"))
            .body("errMsg", equalTo("MISSING_REQUIRED_VALUE : [cryptoContent]"));
    }

    /** [VTC_getPersonalDecryption_emptyCryptoContent] cryptoContent가 빈 문자열 → 001 (CommonUtil.isNull은 빈 문자열도 null 취급) */
    @Test
    void VTC_getPersonalDecryption_emptyCryptoContent() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", "")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("001"))
            .body("errMsg", equalTo("MISSING_REQUIRED_VALUE : [cryptoContent]"));
    }

    // ==================== ATC ====================

    /** [ATC_getPersonalDecryption_invalidCiphertext] 복호화 불가능한 값 → 서비스 내부에서 캐치, err=115 */
    @Test
    void ATC_getPersonalDecryption_invalidCiphertext() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", "not-a-valid-kms-ciphertext")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("115"));
    }

    /** [ATC_getPersonalDecryption_noSession] 세션 없이 접근 → /web/login 으로 302 리다이렉트 */
    @Test
    void ATC_getPersonalDecryption_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType(ContentType.URLENC)
            .formParam("cryptoContent", "irrelevant")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(302);
    }
}

