        TestUtil.executeSql(dbConnection, "sql/admin-client-list-setup.sql", AdminClientListBlackBoxTest.class);

        sessionId = TestUtil.adminLogin(BASE_URL, "clientadmin", "testpw", dbConnection);
    }

    @AfterAll
